import { ref, watch, onMounted } from 'vue';

export const useAutoTheme = (props, autoThemeDetection = true) => {
  const themeState = ref(props.theme);

  /* eslint-disable no-restricted-globals */
  const setTheme = (newTheme) => {
    if (newTheme === 'ios' || newTheme === 'material') {
      if (themeState.value !== newTheme) {
        themeState.value = newTheme;
      }
    } else if (
      autoThemeDetection &&
      themeState.value === 'parent' &&
      typeof window !== 'undefined' &&
      typeof document !== 'undefined'
    ) {
      const htmlEl = document.documentElement;
      if (htmlEl) {
        if (htmlEl.classList.contains('ios')) {
          themeState.value = 'ios';
        } else if (
          htmlEl.classList.contains('md') ||
          htmlEl.classList.contains('material')
        ) {
          themeState.value = 'material';
        }
      }
    }
  };
  /* eslint-enable no-restricted-globals */

  watch(
    () => props.theme,
    (newTheme) => {
      setTheme(newTheme);
    }
  );
  onMounted(() => {
    setTheme(props.theme);
  });

  return themeState;
};

import { computed, onMounted, onUnmounted, ref, toValue } from 'vue';

import { effectiveDarkValue } from './effective-dark-value.js';

export function useEffectiveDark(darkProp) {
  const prefersDark = ref(false);
  let media;
  let listener;

  onMounted(() => {
    if (typeof window === 'undefined') return;
    media = window.matchMedia('(prefers-color-scheme: dark)');
    prefersDark.value = media.matches;
    listener = () => {
      prefersDark.value = media.matches;
    };
    if (media.addEventListener) {
      media.addEventListener('change', listener);
    } else {
      media.addListener(listener);
    }
  });

  onUnmounted(() => {
    if (media && listener) {
      if (media.removeEventListener) {
        media.removeEventListener('change', listener);
      } else {
        media.removeListener(listener);
      }
    }
  });

  return computed(() =>
    effectiveDarkValue(toValue(darkProp), prefersDark.value),
  );
}

export function effectiveDarkValue(darkValue, prefersDark) {
  if (darkValue === undefined || darkValue === null) {
    return prefersDark;
  }
  return darkValue;
}

import { inject } from 'vue';

export const useContext = () => {
  return inject('TailwindCapacitorContext');
};

const useDarkClasses = (classNames, context) => {
  if (!context || !context.value.dark) return '';
  return classNames;
};
const createUseDarkClasses = (context) => (classNames) =>
  useDarkClasses(classNames, context);

export { createUseDarkClasses as darkClasses, useDarkClasses };

import { computed } from 'vue';
import { cls } from '../../shared/cls.js';

const propClasses = (classesObj, theme, state) => {
  if (typeof classesObj === 'string') return classesObj;
  const arr = [classesObj.common, classesObj[theme]];
  if (state && classesObj[state]) {
    if (typeof classesObj[state] === 'string') arr.push(classesObj[state]);
    else {
      arr.push(classesObj[state].common, classesObj[state][theme]);
    }
  }
  return arr;
};
const themeClasses = (classesObj, theme, addBaseClassName) => {
  const c = {};
  const themeSubKeys = ['common', 'ios', 'material'];
  Object.keys(classesObj).forEach((key) => {
    const addBaseClass = key === 'base' ? addBaseClassName : '';
    const hasStates =
      typeof classesObj[key] !== 'string' &&
      Object.keys(classesObj[key]).filter(
        (state) => !themeSubKeys.includes(state)
      ).length > 0;
    if (!hasStates) {
      c[key] = cls(propClasses(classesObj[key], theme), addBaseClass);
      return;
    }
    c[key] = {};
    const defaultStateClasses = propClasses(classesObj[key], theme);
    c[key].default = cls(defaultStateClasses, addBaseClass);
    Object.keys(classesObj[key])
      .filter((state) => !themeSubKeys.includes(state))
      .forEach((state) => {
        c[key][state] = cls(
          defaultStateClasses,
          propClasses(classesObj[key], theme, state),
          addBaseClass
        );
      });
  });
  return c;
};

const useThemeClasses = (props, classesObj, ctx) =>
  computed(() => {
    let theme;
    if (ctx) {
      theme = ctx.value.theme || 'ios';
    }
    if (props.ios) theme = 'ios';
    if (props.material) theme = 'material';
    return themeClasses(
      typeof classesObj === 'function' ? classesObj() : classesObj,
      theme
    );
  });

const createUseThemeClasses = (context) => (props, classesObj) =>
  useThemeClasses(props, classesObj, context);
export { useThemeClasses, createUseThemeClasses as themeClasses };

import { computed } from 'vue';

const useTheme = (props = {}, context) =>
  computed(() => {
    let theme;
    if (context) {
      theme = context.value.theme || 'ios';
    }
    if (props.ios) theme = 'ios';
    if (props.material) theme = 'material';
    return theme;
  });

export { useTheme };

import { ref, onMounted, onBeforeUnmount, watch } from 'vue';
import { TouchRipple } from '../../shared/touch-ripple-class.js';

export const useTouchRipple = (
  elRef,
  props,
  { addCondition, eventsElRef, context } = {}
) => {
  if (!eventsElRef) eventsElRef = elRef;
  const ripple = ref(null);
  let eventsAttached = false;

  const getEl = (reference) => {
    if (!reference || !reference.value) return null;
    let el = reference.value;
    if (el.$el) el = el.$el;
    return el;
  };

  const theme = () => {
    let value = context.value.theme || 'ios';
    if (props.ios) value = 'ios';
    if (props.material) value = 'material';
    return value;
  };
  const needsTouchRipple = () => {
    return (
      theme() === 'material' &&
      props.touchRipple &&
      (addCondition ? addCondition() : true)
    );
  };
  const removeRipple = () => {
    if (ripple.value) ripple.value.remove();
    ripple.value = null;
  };

  const onPointerDown = (e) => {
    ripple.value = new TouchRipple(getEl(elRef), e.pageX, e.pageY);
  };
  const onPointerMove = () => {
    removeRipple();
  };
  const onPointerUp = () => {
    removeRipple();
  };

  const attachEvents = () => {
    if (!context.value.touchRipple || eventsAttached) return;
    eventsAttached = true;
    const el = getEl(eventsElRef);
    el.addEventListener('pointerdown', onPointerDown);
    el.addEventListener('pointermove', onPointerMove);
    el.addEventListener('pointerup', onPointerUp);
    el.addEventListener('pointercancel', onPointerUp);
    el.addEventListener('contextmenu', onPointerUp);
  };
  const detachEvents = () => {
    eventsAttached = false;
    const el = getEl(eventsElRef);
    el.removeEventListener('pointerdown', onPointerDown);
    el.removeEventListener('pointermove', onPointerMove);
    el.removeEventListener('pointerup', onPointerUp);
    el.removeEventListener('pointercancel', onPointerUp);
    el.removeEventListener('contextmenu', onPointerUp);
  };

  watch(
    () => needsTouchRipple(),
    (newV) => {
      if (newV) attachEvents();
      else detachEvents();
    }
  );

  onMounted(() => {
    if (!getEl(eventsElRef) || !needsTouchRipple()) return;
    attachEvents();
  });

  onBeforeUnmount(() => {
    if (!getEl(eventsElRef) || !needsTouchRipple()) return;
    detachEvents();
  });
};
